import type { Attribute, Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  resizableHandleClassName,
  resizablePanelClassName,
  resizablePanelGroupClassName,
  resizablePanelGroupDirectionClassName,
} from "./view";

export {
  resizableHandleClassName,
  resizablePanelClassName,
  resizablePanelGroupClassName,
  resizablePanelGroupDirectionClassName,
} from "./view";

export type ResizableDirection = "horizontal" | "vertical";
export type ResizableStyle = Readonly<Record<string, string>>;

export type PanelGroupViewConfig = Readonly<{
  children: readonly Html[];
  direction?: ResizableDirection;
  className?: string;
  style?: ResizableStyle;
}>;

export type PanelViewConfig = Readonly<{
  children: readonly (Html | string)[];
  size?: number;
  className?: string;
  style?: ResizableStyle;
}>;

export type HandleViewConfig<ParentMessage> = Readonly<{
  direction?: ResizableDirection;
  label?: string;
  className?: string;
  style?: ResizableStyle;
  attributes?: readonly Attribute<ParentMessage>[];
}>;

export type PanelItem = Readonly<{
  children: readonly (Html | string)[];
  size?: number;
}>;

const classNames = (...values: readonly (string | undefined)[]): string =>
  values
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const panelGroupView = <ParentMessage>({
  children,
  direction = "horizontal",
  className,
  style,
}: PanelGroupViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.DataAttribute("slot", "resizable-panel-group"),
      h.DataAttribute("direction", direction),
      h.Class(
        classNames(
          resizablePanelGroupClassName,
          resizablePanelGroupDirectionClassName(direction),
          className
        )
      ),
      ...(style === undefined ? [] : [h.Style(style)]),
    ],
    children
  );
};

export const panelView = <ParentMessage>({
  children,
  size,
  className,
  style,
}: PanelViewConfig): Html => {
  const h = html<ParentMessage>();
  const sizeStyle =
    size === undefined
      ? {}
      : {
          flex: `0 0 ${size}%`,
        };

  return h.div(
    [
      h.DataAttribute("slot", "resizable-panel"),
      ...(size === undefined ? [] : [h.DataAttribute("size", String(size))]),
      h.Class(classNames(resizablePanelClassName, className)),
      h.Style({ ...sizeStyle, ...style }),
    ],
    children
  );
};

export const handleView = <ParentMessage>({
  direction = "horizontal",
  label = "Resize panels",
  className,
  style,
  attributes = [],
}: HandleViewConfig<ParentMessage> = {}): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Role("separator"),
      h.AriaLabel(label),
      h.AriaOrientation(direction),
      h.DataAttribute("slot", "resizable-handle"),
      h.DataAttribute("direction", direction),
      h.Class(classNames(resizableHandleClassName, className)),
      ...(style === undefined ? [] : [h.Style(style)]),
      ...attributes,
    ],
    []
  );
};

export const view = <ParentMessage>({
  panels,
  direction = "horizontal",
  className,
}: Readonly<{
  panels: readonly PanelItem[];
  direction?: ResizableDirection;
  className?: string;
}>): Html =>
  panelGroupView<ParentMessage>({
    direction,
    ...(className === undefined ? {} : { className }),
    children: panels.flatMap((panel, index) => [
      ...(index === 0 ? [] : [handleView<ParentMessage>({ direction })]),
      panelView<ParentMessage>({
        children: panel.children,
        ...(panel.size === undefined ? {} : { size: panel.size }),
      }),
    ]),
  });

export const resizablePanelGroupClassName =
  "flex h-full w-full overflow-hidden rounded-lg border border-gray-200 bg-white";

export const resizablePanelGroupDirectionClassName = (
  direction: "horizontal" | "vertical"
): string => (direction === "vertical" ? "flex-col" : "flex-row");

export const resizablePanelClassName =
  "flex items-center justify-center p-6 text-sm font-medium text-gray-950";

export const resizableHandleClassName =
  "relative flex shrink-0 items-center justify-center bg-transparent outline-none after:absolute after:bg-gray-400 focus-visible:ring-2 focus-visible:ring-accent-500 data-[direction=horizontal]:w-3 data-[direction=horizontal]:cursor-col-resize data-[direction=horizontal]:after:h-4 data-[direction=horizontal]:after:w-px data-[direction=vertical]:h-3 data-[direction=vertical]:cursor-row-resize data-[direction=vertical]:after:h-px data-[direction=vertical]:after:w-4";

import { Option } from "effect";
import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Resizable from "./index";

type Message = Readonly<{ readonly _tag: "PressedHandle" }>;

const view = (): Html => {
  const h = html<Message>();

  return Resizable.panelGroupView<Message>({
    children: [
      Resizable.panelView<Message>({ size: 30, children: ["Sidebar"] }),
      Resizable.handleView<Message>({
        attributes: [
          h.OnPointerDown(() => Option.some({ _tag: "PressedHandle" })),
        ],
      }),
      Resizable.panelView<Message>({ size: 70, children: ["Content"] }),
    ],
  });
};

describe("Resizable registry view", () => {
  test("renders controlled panel anatomy with opt-in handle behavior", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.text("Sidebar")).toHaveAttr("data-size", "30"),
      Scene.expect(Scene.text("Content")).toHaveAttr("data-size", "70"),
      Scene.expect(
        Scene.role("separator", { name: "Resize panels" })
      ).toExist(),
      Scene.expect(
        Scene.role("separator", { name: "Resize panels" })
      ).toHaveHandler("pointerdown")
    );
  });
});
